using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class FuelSignProbe{static FuelSignProbe(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("FuelSignProbe.request"))return;File.Delete("FuelSignProbe.request");try{var s=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).ToArray();var rows=new System.Collections.Generic.List<string>();var flags=System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic;foreach(var f in all.Where(f=>f.name=="fuel_board"||f.name=="roof_filler")){var d=typeof(FinalPNGCityDetails).GetMethod("Read",flags).Invoke(null,new object[]{f.sharedMesh});var ty=d.GetType();var p=(Vector3[])ty.GetField("p").GetValue(d);var ids=(int[])ty.GetField("ids").GetValue(d);var uv=(Vector2[][])ty.GetField("uv").GetValue(d);var parent=Enumerable.Range(0,p.Length).ToArray();Func<int,int> root=null;root=i=>parent[i]==i?i:parent[i]=root(parent[i]);var weld=new System.Collections.Generic.Dictionary<Vector3Int,int>();for(int i=0;i<p.Length;i++){var k=new Vector3Int(Mathf.RoundToInt(p[i].x*10000),Mathf.RoundToInt(p[i].y*10000),Mathf.RoundToInt(p[i].z*10000));if(weld.TryGetValue(k,out var other))parent[root(i)]=root(other);else weld[k]=i;}for(int i=0;i<ids.Length;i+=3){parent[root(ids[i+1])]=root(ids[i]);parent[root(ids[i+2])]=root(ids[i]);}foreach(var group in Enumerable.Range(0,p.Length).GroupBy(root)){var vs=group.ToArray();var bnd=new Bounds(f.transform.TransformPoint(p[vs[0]]),Vector3.zero);foreach(int i in vs)bnd.Encapsulate(f.transform.TransformPoint(p[i]));var uvavg=vs.Select(i=>uv[0][i]).Aggregate(Vector2.zero,(x,y)=>x+y)/vs.Length;rows.Add(f.name+" component="+group.Key+" vertices="+vs.Length+" bounds="+bnd+" uv="+uvavg);}rows.Add("transform "+f.name+" "+f.transform.localToWorldMatrix);typeof(FinalPNGCityDetails).GetMethod("Capture",flags).Invoke(null,new object[]{s,new Vector3(467,36,120),new Vector3(454,33,105),"Fuel-Before"});}File.WriteAllLines("FinalEnvironmentRoadReview/FuelSignProbe.txt",rows);}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/FuelSignProbe.txt",e.ToString());}}}

